script:
// What in the workspace needs an administrator now (one/home.py, attention).
// Nothing, and the block takes no room on Home.
frappe.xcall("onedesk.one.home.attention").then((rows) => {
	const box = root_element.querySelector(".one-needs");
	const block = root_element.host.closest(".ce-block");
	if (!rows.length) {
		if (block) block.style.display = "none";
		return;
	}
	const esc = frappe.utils.escape_html;
	box.innerHTML =
		`<div class="one-needs-head"><span class="h4"><b>${esc(__("The Workspace"))}</b></span></div>` +
		rows
			.map((one) => `<a class="one-needs-row" href="${esc(one.route)}">${frappe.ui.alert.html({ title: one.what, description: one.detail, theme: "yellow" })}</a>`)
			.join("");
	// frappe's icons are a sprite in the page, which a shadow root cannot
	// reach: the alert's words carry it without one.
	box.querySelectorAll(".es-alert svg").forEach((icon) => icon.remove());
});

style:
/* As a workspace header draws (desktop.scss, .ce-header .h4). */
.one-needs { margin: 0 -7px; }
.one-needs-head { margin: 0 0 12px; }
.one-needs-head .h4 { font-size: var(--text-lg); color: var(--text-light); }
.one-needs-row { display: block; margin-bottom: 8px; text-decoration: none; color: inherit; }
.one-needs-row:hover { text-decoration: none; }
